/**
 * Belajar Ads (belajarads.com)
 * Production Application Entry Point for WebNesia cPanel / Phusion Passenger
 *
 * This entry point delegates to the Next.js standalone server generated by "npm run build".
 * Next.js Standalone compiles all application routes, components, and dependencies into
 * a lightweight bundle optimized for production hosting environments like cPanel.
 */

const fs = require('fs');
const path = require('path');

const standaloneEntry = path.join(__dirname, '.next', 'standalone', 'server.js');

if (!fs.existsSync(standaloneEntry)) {
  console.error('[BelajarAds] Production build output not found at: ' + standaloneEntry);
  console.error('[BelajarAds] Please run "npm run build" in the application root to compile the application.');

  // Provide a graceful fallback HTTP response if Passenger starts before initial build
  const http = require('http');
  const port = parseInt(process.env.PORT, 10) || 3000;
  const fallbackServer = http.createServer((req, res) => {
    res.writeHead(503, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end(`<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="utf-8">
  <title>Belajar Ads - Setup in Progress</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; display: flex; align-items: center; justify-content: center; height: 100vh; margin: 0; background: #0b0f19; color: #f3f4f6; }
    .card { background: #111827; border: 1px solid #1f2937; border-radius: 12px; padding: 32px; max-width: 520px; text-align: center; box-shadow: 0 10px 25px rgba(0,0,0,0.5); }
    h1 { color: #f97316; font-size: 22px; margin-bottom: 12px; }
    p { color: #9ca3af; font-size: 14px; line-height: 1.6; }
    code { background: #1f2937; color: #fdba74; padding: 3px 8px; border-radius: 4px; font-size: 13px; }
  </style>
</head>
<body>
  <div class="card">
    <h1>Belajar Ads — Aplikasi Sedang Disiapkan</h1>
    <p>Build standalone produksi belum ditemukan pada server.</p>
    <p>Jalankan perintah berikut di cPanel Terminal pada direktori <code>repositories/belajar-ads</code>:</p>
    <p><code>npm run build</code></p>
    <p style="margin-top:20px; font-size: 12px; color: #6b7280;">Setelah build selesai, refresh halaman ini atau Restart Node.js Application di cPanel.</p>
  </div>
</body>
</html>`);
  });

  fallbackServer.listen(port, () => {
    console.log('[BelajarAds] Standby fallback server listening on port ' + port);
  });
} else {
  // Delegate directly to the compiled Next.js standalone server
  require(standaloneEntry);
}
